#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 1024
#define MAXT 64
#define SPIN_LIMIT (1L << 22)

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static inline void cpu_relax(void)
{
#if defined(__x86_64__) || defined(__i386__)
    __builtin_ia32_pause();
#elif defined(__aarch64__)
    __asm__ __volatile__("yield");
#endif
}

/* Computes (or accumulates into) an mr x nr tile of C from packed A and B panels. */
static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    v8 r[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                   {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc) {
                stu(cp, ldu(cp) + r[i][0]);
                stu(cp + 8, ldu(cp + 8) + r[i][1]);
            } else {
                stu(cp, r[i][0]);
                stu(cp + 8, r[i][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int i = 0; i < MR; i++) {
            memcpy(&tmp[i][0], &r[i][0], sizeof(v8));
            memcpy(&tmp[i][8], &r[i][1], sizeof(v8));
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

/* Packs an mc x kc block of A into MR-row panels (k-major), zero-padding the last one. */
static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *restrict Ap)
{
    for (int ip = 0; ip < mc; ip += MR) {
        int rows = mc - ip < MR ? mc - ip : MR;
        float *d = Ap + (size_t)ip * kc;
        const float *s = A + (size_t)(i0 + ip) * n + p0;
        if (rows == MR) {
            const float *s0 = s, *s1 = s + n, *s2 = s + 2 * (size_t)n;
            const float *s3 = s + 3 * (size_t)n, *s4 = s + 4 * (size_t)n, *s5 = s + 5 * (size_t)n;
            for (int k = 0; k < kc; k++) {
                d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                d += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < rows; r++) d[r] = s[(size_t)r * n + k];
                for (; r < MR; r++) d[r] = 0.0f;
                d += MR;
            }
        }
    }
}

static void pack_b(const float *B, int n, int p0, int kc, int j0, int nc, float *restrict Bp)
{
    for (int jp = 0; jp < nc; jp += NR) {
        int cols = nc - jp < NR ? nc - jp : NR;
        float *dst = Bp + (size_t)jp * kc;
        for (int k = 0; k < kc; k++) {
            const float *src = B + (size_t)(p0 + k) * n + j0 + jp;
            float *d = dst + k * NR;
            if (cols == NR) {
                memcpy(d, src, NR * sizeof(float));
            } else {
                int j = 0;
                for (; j < cols; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }
    }
}

static float g_Ap[MAXT][MC * KC] __attribute__((aligned(64)));
static float g_Bp[MAXT][KC * NC] __attribute__((aligned(64)));

static void gemm_rows(const float *A, const float *B, float *C, int n, int r0, int r1,
                      float *Ap, float *Bp)
{
    if (r0 >= r1) return;
    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int acc = pc != 0;
            pack_b(B, n, pc, kc, jc, nc, Bp);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                pack_a(A, n, ic, mc, pc, kc, Ap);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nr = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)jr * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(ic + ir) * n + jc + jr, n, mr, nr, acc);
                    }
                }
            }
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, nt, chunk;
} job_t;

static job_t g_job;

static void run(int tid)
{
    job_t *j = &g_job;
    if (tid >= j->nt) return;
    int r0 = tid * j->chunk, r1 = r0 + j->chunk;
    if (r0 > j->n) r0 = j->n;
    if (r1 > j->n) r1 = j->n;
    gemm_rows(j->A, j->B, j->C, j->n, r0, r1, g_Ap[tid], g_Bp[tid]);
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
            } else {
                pthread_mutex_lock(&g_mu);
                while (__atomic_load_n(&g_gen, __ATOMIC_ACQUIRE) == seen)
                    pthread_cond_wait(&g_cv, &g_mu);
                pthread_mutex_unlock(&g_mu);
                spins = 0;
            }
        }
        seen = g;
        run(tid);
        __atomic_sub_fetch(&g_remaining, 1, __ATOMIC_ACQ_REL);
    }
    return NULL;
}

static void pool_init(void)
{
    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    int hw = ncpu > 0 ? (int)ncpu : 1;
    if (hw > MAXT) hw = MAXT;
    int created = 0;
    for (int t = 1; t < hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
    }
    g_pool = created;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (g_pool < 0) pool_init();

    int nt = g_pool + 1;
    if (n < 128) nt = 1;
    int max_by_rows = (n + MR * 4 - 1) / (MR * 4);
    if (nt > max_by_rows) nt = max_by_rows;
    if (nt < 1) nt = 1;

    int chunk = (n + nt - 1) / nt;
    chunk = (chunk + MR - 1) / MR * MR;
    while (nt > 1 && (long)chunk * (nt - 1) >= n) nt--;

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C;
    j->n = n; j->nt = nt; j->chunk = nt == 1 ? n : chunk;

    if (nt == 1 || g_pool == 0) {
        j->nt = 1;
        j->chunk = n;
        run(0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
